package com.thakur.employee.controller; import com.fasterxml.jackson.databind.ObjectMapper;import com.thakur.employee.model.*;import com.thakur.employee.repository.UserRepository;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; @SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class AuthControllerTest {@Autowired MockMvc mvc;@Autowired UserRepository repo;@Autowired PasswordEncoder encoder;@Autowired ObjectMapper mapper;@BeforeEach void setup(){repo.deleteAll();repo.save(AppUser.builder().name("Test").email("test@test.com").password(encoder.encode("Password@123")).department("IT").role(Role.EMPLOYEE).build());}@Test void loginReturnsToken()throws Exception{mvc.perform(post("/api/auth/login").contentType("application/json").content("{\"email\":\"test@test.com\",\"password\":\"Password@123\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.token").isNotEmpty());}}
